import base64
script=r'''import csv
import sys
import numpy as np

COUNTS_PATH, GENES_PATH, SAMPLES_PATH, OUTPUT_PATH = sys.argv[1:5]
CELL_TYPES = (\"CD4\", \"CD8\", \"CD14\", \"CD19\")

sample_celltype = {}
with open(SAMPLES_PATH, newline=\"\", encoding=\"utf-8-sig\") as handle:
    reader = csv.DictReader(handle)
    required = {\"sample\", \"celltype\"}
    if not required.issubset(reader.fieldnames or []):
        raise ValueError(\"Sample annotation must contain sample and celltype columns\")
    for row in reader:
        sample = row[\"sample\"]
        if sample in sample_celltype:
            raise ValueError(\"Duplicate sample annotation: \" + sample)
        sample_celltype[sample] = row[\"celltype\"]

gene_meta = {}
with open(GENES_PATH, newline=\"\", encoding=\"utf-8-sig\") as handle:
    reader = csv.DictReader(handle)
    fields = reader.fieldnames or []
    if not fields or \"Length\" not in fields or \"gene_biotype\" not in fields:
        raise ValueError(\"Gene metadata must contain an identifier, Length, and gene_biotype\")
    identifier_field = fields[0]
    for row in reader:
        gene = row[identifier_field]
        if gene in gene_meta:
            raise ValueError(\"Duplicate gene metadata identifier: \" + gene)
        gene_meta[gene] = (float(row[\"Length\"]), row[\"gene_biotype\"])

lengths = []
means = {cell_type: [] for cell_type in CELL_TYPES}
sample_indices = {}
seen_genes = set()
with open(COUNTS_PATH, newline=\"\", encoding=\"utf-8-sig\") as handle:
    reader = csv.reader(handle)
    header = next(reader)
    if len(header) < 2:
        raise ValueError(\"Expression matrix has no sample columns\")
    sample_names = header[1:]
    if len(sample_names) "'!= len(set(sample_names)):
        raise ValueError("Expression matrix contains duplicate sample columns")
    missing_annotations = [sample for sample in sample_names if sample not in sample_celltype]
    if missing_annotations:
        raise ValueError("Expression samples missing annotations: " + ",".join(missing_annotations[:5]))
    for cell_type in CELL_TYPES:
        sample_indices[cell_type] = [i + 1 for i, sample in enumerate(sample_names) if sample_celltype[sample] == cell_type]
        if not sample_indices[cell_type]:
            raise ValueError("No samples for cell type " + cell_type)
    for row_number, row in enumerate(reader, start=2):
        if len(row) != len(header):
            raise ValueError("Expression row width mismatch at row " + str(row_number))
        gene = row[0]
        if gene in seen_genes:
            raise ValueError("Duplicate expression gene identifier: " + gene)
        seen_genes.add(gene)
        if gene not in gene_meta:
            raise ValueError("Expression gene missing metadata: " + gene)
        length, biotype = gene_meta[gene]
        if biotype != "protein_coding":
            continue
        lengths.append(length)
        for cell_type in CELL_TYPES:
            values = np.fromiter((float(row[i]) for i in sample_indices[cell_type]), dtype=np.float64, count=len(sample_indices[cell_type]))
            means[cell_type].append(float(np.mean(values)))

if not lengths:
    raise ValueError("No genes matched exact biotype protein_coding")
if seen_genes != set(gene_meta):
    absent = sorted(set(gene_meta) - seen_genes)
    raise ValueError("Gene metadata identifiers missing from expression matrix: " + ",".join(absent[:5]))

length_array = np.asarray(lengths, dtype=np.float64)
results = {}
for cell_type in CELL_TYPES:
    mean_array = np.asarray(means[cell_type], dtype=np.float64)
    if not np.all(np.isfinite(mean_array)) or not np.all(np.isfinite(length_array)):
        raise ValueError("Non-finite values encountered")
    results[cell_type] = float(np.corrcoef(length_array, mean_array)[0, 1])
weakest = min(CELL_TYPES, key=lambda cell_type: abs(results[cell_type]))

with open(OUTPUT_PATH, "w", newline="", encoding="utf-8") as handle:
    writer = csv.writer(handle, delimiter="'"\\t\", lineterminator=\"\\n\")
    writer.writerow([\"cell_type\", \"sample_count\", \"protein_coding_gene_count\", \"pearson_r\", \"abs_pearson_r\", \"is_weakest\", \"numpy_version\", \"expression_aggregation\", \"gene_filter\"])
    for cell_type in CELL_TYPES:
        coefficient = results[cell_type]
        writer.writerow([cell_type, len(sample_indices[cell_type]), len(lengths), format(coefficient, \".17g\"), format(abs(coefficient), \".17g\"), \"true\" if cell_type == weakest else \"false\", np.__version__, \"arithmetic_mean_untransformed_batch_corrected_counts\", \"gene_biotype_exactly_protein_coding\"])
'''
print(base64.b64encode(script.encode()).decode())
PY"

